KG42.register("rules-5606799d442e2be738f9844f",{"id":"27-multiple_microgrid_trading::v141-c-R005","paper":"27-multiple_microgrid_trading","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01","name":"Price-signal coordination","process_stage":"coordination","market_meaning":"Submitted purchase requests from neighboring microgrids are collected and used to update the receiving microgrid's price signal. Scope: At each microgrid during distributed trading iterations among neighboring islanded microgrids. The locally updated energy offer ε_i^{(s)}[k] supplies an input to computing the next price signal. Scope: At μG-i during each distributed price-update iteration. Each microgrid receives neighboring energy requests and performs the price-signal update that coordinates market clearing. Scope: The local coordinating role performed by each μG-i in the distributed trading algorithm. Exchange of purchase bids precedes the distributed regulation phase that adjusts price signals. Scope: Within each iteration of the two-step distributed trading algorithm. The coordination procedure iterates until global agreement is reached on prices and transferred energies. Scope: The two-step distributed price-coordination procedure among islanded microgrids.","independence_rationale":"Relations governed by the approved function coordination.price_signal under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","coordination.local_operator","coordination.price_signal"],"E":[{"edge_id":"v141-c-R005-E001","source":"bidding.demand","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g20-e020","v141-b-g22-e022"]},{"edge_id":"v141-c-R005-E002","source":"bidding.demand","target":"coordination.price_signal","type":"precedes","constraint_ids":["v141-c-R005-C004"],"evidence_ids":["v141-b-g03-e003","v141-b-g22-e022"]},{"edge_id":"v141-c-R005-E003","source":"bidding.supply","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R005-C002"],"evidence_ids":["v141-b-g22-e022","v141-b-g24-e024"]},{"edge_id":"v141-c-R005-E004","source":"coordination.local_operator","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R005-C003"],"evidence_ids":["v141-b-g20-e020","v141-b-g22-e022","v141-b-g24-e024"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"At each microgrid during distributed trading iterations among neighboring islanded microgrids. | At μG-i during each distributed price-update iteration. | The local coordinating role performed by each μG-i in the distributed trading algorithm. | The two-step distributed price-coordination procedure among islanded microgrids. | Within each iteration of the two-step distributed trading algorithm.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g03-e003","v141-b-g20-e020","v141-b-g22-e022","v141-b-g24-e024"]},"x":[{"variable_id":"v141-c-R005-x01","symbol":"λ_i[k]","meaning":"Selling price signal of μG-i at distributed iteration k; the source interprets the Lagrange multiplier λ_i as the price per energy unit requested by μG-i to sell energy to neighbors.","kind":"operational","domain":"real-valued scalar price signal; the supplied source states no explicit sign restriction for λ_i","unit":null,"indices":["i","k"],"evidence_ids":["v141-b-g23-e023","v141-b-g22-e022","v141-b-g24-e024"]},{"variable_id":"v141-c-R005-x02","symbol":"ε_i^{(s)}[k]","meaning":"Energy offered for sale locally by μG-i at iteration k, computed by solving local subproblem (6) with fixed λ[k].","kind":"operational","domain":"nonnegative real; the source imposes ε_i^{(s)} ≥ 0 in (6)","unit":"MWh","indices":["i","k"],"evidence_ids":["v141-b-g22-e022","v141-b-g16-e016","v141-b-g24-e024"]},{"variable_id":"v141-c-R005-x03","symbol":"E_i^{(s)}[k]","meaning":"Vector of energy quantities sold by μG-i to its neighbors at iteration k, built from neighbor-specific quantities E_{i,j}[k].","kind":"operational","domain":"nonnegative energy vector whose directed entries are constrained by E_{i,j} ≥ 0 in (3)-(4)","unit":"MWh","indices":["i","k"],"evidence_ids":["v141-b-g22-e022","v141-b-g20-e020","v141-b-g06-e006"]}],"theta":[{"parameter_id":"v141-c-R005-p01","symbol":"α[k]","meaning":"Positive step factor used in the distributed price-signal update at iteration k.","value":{"kind":"symbolic","number_value":null,"text_value":"positive step factor"},"unit":null,"indices":["k"],"evidence_ids":["v141-b-g20-e020","v141-b-g22-e022"]},{"parameter_id":"v141-c-R005-p02","symbol":"A","meaning":"M×M adjacency matrix [a_{i,j}] where a_{i,j}=1 iff a directed connection from μG-i to μG-j exists; a_{i,i}=0 and A may be nonsymmetric.","value":{"kind":"symbolic","number_value":null,"text_value":"a_{i,j} ∈ {0,1}; a_{i,i}=0"},"unit":null,"indices":["i","j"],"evidence_ids":["v141-b-g06-e006","v141-b-g20-e020"]},{"parameter_id":"v141-c-R005-p03","symbol":"e_i","meaning":"ith column of the M×M identity matrix, used as a selector in e_i^T A E_i^{(s)}[k].","value":{"kind":"symbolic","number_value":null,"text_value":"ith identity column"},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g10-e010","v141-b-g20-e020"]}],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Submitted purchase requests from neighboring microgrids are collected and used to update the receiving microgrid's price signal. Scope: At each microgrid during distributed trading iterations among neighboring islanded microgrids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g20-e020","v141-b-g22-e022"]},{"constraint_id":"v141-c-R005-C002","kind":"mathematical","role":"core","statement":"The locally updated energy offer ε_i^{(s)}[k] supplies an input to computing the next price signal. Scope: At μG-i during each distributed price-update iteration.","expression":"λ_i[k+1] = λ_i[k] + α[k] (e_i^T A E_i^{(s)}[k] - ε_i^{(s)}[k])","formalization_origin":"source","template_id":null,"members":["bidding.supply","coordination.price_signal"],"variable_refs":["v141-c-R005-x01","v141-c-R005-x02","v141-c-R005-x03"],"parameter_refs":["v141-c-R005-p01","v141-c-R005-p02","v141-c-R005-p03"],"evidence_ids":["v141-b-g22-e022","v141-b-g24-e024"]},{"constraint_id":"v141-c-R005-C003","kind":"mathematical","role":"core","statement":"Each microgrid receives neighboring energy requests and performs the price-signal update that coordinates market clearing. Scope: The local coordinating role performed by each μG-i in the distributed trading algorithm.","expression":"λ_i[k+1] = λ_i[k] + α[k] (e_i^T A E_i^{(s)}[k] - ε_i^{(s)}[k])","formalization_origin":"source","template_id":null,"members":["coordination.local_operator","coordination.price_signal"],"variable_refs":["v141-c-R005-x01","v141-c-R005-x02","v141-c-R005-x03"],"parameter_refs":["v141-c-R005-p01","v141-c-R005-p02","v141-c-R005-p03"],"evidence_ids":["v141-b-g20-e020","v141-b-g22-e022","v141-b-g24-e024"]},{"constraint_id":"v141-c-R005-C004","kind":"procedural","role":"core","statement":"Exchange of purchase bids precedes the distributed regulation phase that adjusts price signals. Scope: Within each iteration of the two-step distributed trading algorithm.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-e003","v141-b-g22-e022"]},{"constraint_id":"v141-c-R005-C005","kind":"procedural","role":"core","statement":"The coordination procedure iterates until global agreement is reached on prices and transferred energies. Scope: The two-step distributed price-coordination procedure among islanded microgrids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-e003"]},{"constraint_id":"v141-c-R005-C006","kind":"mathematical","role":"supporting","statement":"If the energy offered by μG-i ε_i^{(s)}[k] is less than the total energy demanded by neighboring μGs from μG-i, e_i^T A E_i^{(s)}[k], then the selling price must increase, λ_i[k+1] ≥ λ_i[k]. Scope: The selling-price update at μG-i during distributed intermicrogrid clearing, as stated in the law-of-demand interpretation.","expression":"ε_i^{(s)}[k] \u003c e_i^T A E_i^{(s)}[k] ⇒ λ_i[k+1] ≥ λ_i[k]","formalization_origin":"source","template_id":null,"members":["bidding.demand","bidding.supply","coordination.price_signal"],"variable_refs":["v141-c-R005-x01","v141-c-R005-x02","v141-c-R005-x03"],"parameter_refs":["v141-c-R005-p02","v141-c-R005-p03"],"evidence_ids":["v141-b-g24-e024"]}],"pi":[{"evidence_id":"v141-b-g03-e003","location":{"location_id":"src-f5dd785b87-p02-c1r4__v141-a-M01-bidding","page":2,"printed_page":null,"section":"I. Introduction","anchor_text":"propose an algorithm based on dual decomposition that itera- tively solves the problem in a distribu","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Interestingly, each iteration of the resulting algorithm has a straightforward interpretation in economical terms once the new operational variables we introduce are given the meaning of energy prices. First, each microgrid locally computes the amounts of energy it must produce, buy, and sell to minimize its local cost according to the current energy prices. Then, after exchanging the microgrid bids, a regulation phase follows, in which, in a distributed way, the energy prices are adjusted according to the law of demand. This two-step process iterates until a global agreement is reached about prices and transferred energies."},{"evidence_id":"v141-b-g20-e020","location":{"location_id":"src-f5dd785b87-p04-c1r2__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III-A. Decentralizing the Problem","anchor_text":"t at t e set o vecto s { i } ca be ead y de ved ow g set {E(b)i }. Note that vector ς = [eTi AE(s)i ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"where α[k] is a positive step factor. In addition, recall from (2) that the set of vectors {E_i^{(s)}} can be readily derived knowing set {E_i^{(b)}}. Note that vector ς = [e_i^T A E_i^{(s)}[k] - ε_i^{(s)}[k]]_{M×1} is a subgradient of the dual concave function C(λ) in λ = λ[k], i.e., C(λ) ≤ C(λ[k]) + ς^T(λ - λ[k]) ∀λ. Finally, (8) also says that λ_i can be updated at μG-i once vector E_i^{(s)}[k] has been built with inputs E_{i,j}[k] collected from the neighboring μGs."},{"evidence_id":"v141-b-g22-e022","location":{"location_id":"src-f5dd785b87-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III-A. Decentralizing the Problem","anchor_text":"μG-i initialize λi[0] repeat μGs exchange {λi[k]} sh μG-i computes ε(s)i [k] and E(b)i [k] by solvin","equation_id":"Algorithm 1","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Algorithm 1 Distributed approach μG-i initialize λ_i[0] repeat μGs exchange {λ_i[k]} μG-i computes ε_i^{(s)}[k] and E_i^{(b)}[k] by solving (6) with fixed λ[k] μG-i informs μG-j, j≠i, about the energy it is willing to buy, namely E_{j,i}[k], at the given price λ_j[k] with energy requests E_{i,j}[k] from neighboring μGs, μG-i builds E_i^{(s)}[k] ← [E_{i,1}[k] ... E_{i,M}[k]]^T μG-i computes λ_i[k+1] ← λ_i[k] + α[k](e_i^T A E_i^{(s)}[k] - ε_i^{(s)}[k]) k ← k+1 until convergence condition is verified"},{"evidence_id":"v141-b-g24-e024","location":{"location_id":"src-f5dd785b87-p04-c1r4__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III-A. Decentralizing the Problem","anchor_text":", g ining interpretation: Each Lagrange multiplier λi may be under- costood as the price per energy ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"According to this view, updating step (8) is clearing the market, i.e., prices should be modified until, globally, the energy demand matches the energy offer. Note that (8) is an example of the law of demand: If the energy offered by μG-i ε_i^{(s)}[k] is less than all the energy demanded by the neighboring μGs from μG-i, i.e., e_i^T A E_i^{(s)}, then the selling price must increase, and λ_i[k+1] ≥ λ_i[k]."},{"evidence_id":"v141-b-g06-e006","location":{"location_id":"src-f5dd785b87-p02-c2r2__v141-a-M01-participation","page":2,"printed_page":null,"section":"II. System Model","anchor_text":"to sell energy Ei,j to μG j, j̸ i, and to buy energy Ek,i fromrgy μG-k, k̸=i. Then, the energy equil","equation_id":"(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"where the two M-dimensional column vectors, i.e., E_i^{(b)} = [E_{1,i} ... E_{M,i}]^T, E_i^{(s)} = [E_{i,1} ... E_{i,M}]^T (2) gather all the energy quantities bought and sold, respectively, by μG-i. In addition, we have introduced adjacency matrix A = [a_{i,j}]_{M×M}, where element a_{i,j} is equal to 1 if there exists a connection from μG-i to μG-j and 0 otherwise. Note that, generally, A may be nonsymmetric, meaning that at least two μGs are allowed to exchange energy in one direction only. By convention, we fix a_{i,i}=0. Moreover, a_{i,j}=0 ⇒ E_{i,j}=0 MWh for all i,j=1,...,M."},{"evidence_id":"v141-b-g10-e010","location":{"location_id":"src-f5dd785b87-p03-c1r1__v141-a-M01-clearing","page":3,"printed_page":null,"section":"II. System Model","anchor_text":"GREGORATTI AND MATAMOROS: DISTRIBUTED ENERGY TRADING: MULTIPLE-MIC where ei is the ith column of the","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"where e_i is the ith column of the M×M identity matrix and, with some abuse of notation, we wrote γ(E_i^{(b)})=[γ(E_{1,i}) ... γ(E_{M,i})]^T. In addition, we used (1) to get rid of variables {E_i^{(g)}}. Note that problem (3) considers the μGs as parts of a common system (for instance, they are controlled by the same operator), and the aim is at minimizing the global cost, without focusing on the benefits/losses of each individual μG. We will see later on, however, that the proposed distributed and iterative minimization algorithm opens to a wider sense interpretation, where achieving the global objective implies a cost reduction at every μG."},{"evidence_id":"v141-b-g16-e016","location":{"location_id":"src-f5dd785b87-p03-c2r3__v141-a-M01-clearing","page":3,"printed_page":null,"section":"III-A. Decentralizing the Problem","anchor_text":"we q y, ( )], y g the M coupling constraints and solving the following dual he problem: er C∗= max C","equation_id":"(5)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"C^* = max_λ C(λ) (5) where C(λ) = ∑_{i=1}^M C_i^{(l)}(λ) with the terms C_i^{(l)}(λ) = min_{ε_i^{(s)},E_i^{(b)}} C_i(ε_i^{(s)},E_i^{(b)},λ) s.t. ε_i^{(s)} ≥ 0, E_{j,i} ≥ 0 ∀j, E_i^{(c)} + ε_i^{(s)} - e_i^T A^T E_i^{(b)} ≥ 0. (6)"},{"evidence_id":"v141-b-g23-e023","location":{"location_id":"src-f5dd785b87-p04-c1r4__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III-A. Decentralizing the Problem","anchor_text":", g ining interpretation: Each Lagrange multiplier λi may be under- costood as the price per energy ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Each Lagrange multiplier λ_i may be understood as the price per energy unit requested by μG-i to sell energy to its neighbors. Then, Lagrangian function (7) can be seen as the “net expenditure” (the opposite of the net income) for μG-i, i.e., each μG pays for producing energy, for buying energy, and for transporting the energy it buys. Conversely, the μG is paid for the energy it sells. By solving problem (6), μG-i is thus maximizing its benefit for some given selling (λ_i[k]) and buying (λ_j[k], j≠i) prices per energy unit."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing"],"extras":{"decision_anchor":"coordination.price_signal","graph_fact_supports":[[{"evidence_id":"v141-b-g20-e020","quote":"Finally, (8) also says that λ_i can be updated at μG-i once vector E_i^{(s)}[k] has been built with inputs E_{i,j}[k] collected from the neighboring μGs."},{"evidence_id":"v141-b-g22-e022","quote":"with energy requests E_{i,j}[k] from neighboring μGs, μG-i builds E_i^{(s)}[k] ← [E_{i,1}[k] ... E_{i,M}[k]]^T"}],[{"evidence_id":"v141-b-g22-e022","quote":"μG-i computes ε_i^{(s)}[k] and E_i^{(b)}[k] by solving (6) with fixed λ[k]"},{"evidence_id":"v141-b-g22-e022","quote":"μG-i computes λ_i[k+1] ← λ_i[k] + α[k](e_i^T A E_i^{(s)}[k] - ε_i^{(s)}[k])"},{"evidence_id":"v141-b-g24-e024","quote":"the energy offered by μG-i ε_i^{(s)}[k]"}],[{"evidence_id":"v141-b-g22-e022","quote":"μG-i computes λ_i[k+1] ← λ_i[k] + α[k](e_i^T A E_i^{(s)}[k] - ε_i^{(s)}[k])"},{"evidence_id":"v141-b-g20-e020","quote":"Finally, (8) also says that λ_i can be updated at μG-i once vector E_i^{(s)}[k] has been built with inputs E_{i,j}[k] collected from the neighboring μGs."},{"evidence_id":"v141-b-g24-e024","quote":"updating step (8) is clearing the market, i.e., prices should be modified until, globally, the energy demand matches the energy offer."}],[{"evidence_id":"v141-b-g03-e003","quote":"Then, after exchanging the microgrid bids, a regulation phase follows, in which, in a distributed way, the energy prices are adjusted according to the law of demand."},{"evidence_id":"v141-b-g22-e022","quote":"μG-i informs μG-j, j≠i, about the energy it is willing to buy, namely E_{j,i}[k], at the given price λ_j[k]"}],[{"evidence_id":"v141-b-g03-e003","quote":"This two-step process iterates until a global agreement is reached about prices and transferred energies."}]],"C2_formalization":{"graph_sha256":"5971f770d90757f877db8a9976d38839534da7e9fd23ad6e3772d9f53b5ac04d","applicability":"formalized","reason":"The supplied source gives an explicit distributed price-signal update in equation (8)/Algorithm 1 and a law-of-demand implication for the direction of that update. These are formalized against coordination.price_signal. The remaining procedural order and convergence-stop statements are retained as not_formalized because the supplied source does not define a formal stopping test. B evidence remains unreviewed in this experiment.","bindings":[{"object_id":"v141-c-R005-x01","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E002","v141-c-R005-E003","v141-c-R005-E004"],"rationale":"λ_i[k] is the price signal updated in this rule; its inputs appear through the links into coordination.price_signal from neighbor demand requests, supply offers, and the local operator."},{"object_id":"v141-c-R005-x02","node_ids":["bidding.supply"],"edge_ids":["v141-c-R005-E003"],"rationale":"ε_i^{(s)}[k] is the locally computed offered selling quantity and is an input to the next price signal through the supply-to-price-signal link E003."},{"object_id":"v141-c-R005-x03","node_ids":["bidding.supply"],"edge_ids":["v141-c-R005-E003"],"rationale":"E_i^{(s)}[k] is the vector of energy sold by μG-i assembled from neighbor-specific quantities and used in the price update through the supply-to-price-signal link E003."},{"object_id":"v141-c-R005-p01","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R005-E004"],"rationale":"α[k] scales the local price-update step performed by the coordinating μG-i, so it is bound to the local-operator-to-price-signal link."},{"object_id":"v141-c-R005-p02","node_ids":["bidding.supply"],"edge_ids":["v141-c-R005-E003"],"rationale":"A parameterizes which directed neighbor quantities enter e_i^T A E_i^{(s)}[k] and therefore conditions the supply input to the price-signal update."},{"object_id":"v141-c-R005-p03","node_ids":["bidding.supply"],"edge_ids":["v141-c-R005-E003"],"rationale":"e_i selects μG-i's row when aggregating E_i^{(s)}[k] in the price-update expression."},{"object_id":"v141-c-R005-C002","node_ids":["bidding.supply","coordination.price_signal"],"edge_ids":["v141-c-R005-E003"],"rationale":"The expression is the source-localized update (8)/Algorithm 1 in which ε_i^{(s)}[k] enters with negative sign; it formalizes the supply-to-price-signal relation."},{"object_id":"v141-c-R005-C003","node_ids":["coordination.local_operator","coordination.price_signal"],"edge_ids":["v141-c-R005-E004"],"rationale":"The same source update is executed locally at μG-i; this binds the local-operator-to-price-signal link."},{"object_id":"v141-c-R005-C006","node_ids":["bidding.demand","bidding.supply","coordination.price_signal"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E003"],"rationale":"The law-of-demand inequality compares offered energy against neighbor demand and asserts the direction of the price-signal change, involving demand and supply links into the price signal."}],"revision_requests":[]}},"quarantined_references":[]}});
